def beautiful_pairs(nums1, nums2):
    n = len(nums1)
    # Step 1: duplicate points have distance 0. For each repeated point the
    # lexicographically smallest pair is (first index, second index);
    # take the smallest such pair over all repeated points.
    first = {}
    best_dup = None
    for i in range(n):
        key = (nums1[i], nums2[i])
        if key in first:
            if first[key] is not None:
                cand = (first[key], i)
                if best_dup is None or cand < best_dup:
                    best_dup = cand
                first[key] = None  # this point is already paired
        else:
            first[key] = i
    if best_dup is not None:
        return list(best_dup)

    # Step 2: all points are distinct. Closest pair under Manhattan distance,
    # comparing candidates as (distance, i, j) so ties go to the smallest pair.
    points = sorted((nums1[i], nums2[i], i) for i in range(n))
    INF = (float('inf'), -1, -1)

    def solve(pts):
        m = len(pts)
        if m <= 1:
            return INF
        if m == 2:
            a, b = pts
            dist = abs(a[0] - b[0]) + abs(a[1] - b[1])
            return (dist, min(a[2], b[2]), max(a[2], b[2]))
        mid = m // 2
        xm = pts[mid][0]
        best = min(solve(pts[:mid]), solve(pts[mid:]))
        d = best[0]

        # Only points within d of the dividing line can form a better (or equal) crossing pair
        strip = [p for p in pts if abs(p[0] - xm) <= d]
        strip.sort(key=lambda p: p[1])
        for i in range(len(strip)):
            for j in range(i + 1, len(strip)):
                if strip[j][1] - strip[i][1] > d:
                    break  # too far apart in y; the rest are farther
                p, q = strip[i], strip[j]
                dist = abs(p[0] - q[0]) + abs(p[1] - q[1])
                cand = (dist, min(p[2], q[2]), max(p[2], q[2]))
                if cand < best:
                    best = cand
        return best

    _, i, j = solve(points)
    return [i, j]
